{-| @Backend.Runtime.Kernel.Seal — ChaCha20-Poly1305 sealing and opening. -}
module Pudu.Backend.Runtime.Kernel.Seal (sealKernelParts) where

import Data.Text (Text)

{-| Each part: its name, the parts it needs, and its lines. -}
sealKernelParts :: [(Text, [Text], [Text])]
sealKernelParts =
  [ ("chacha20", [],
      [ "/* ChaCha20: the key stream block for a counter, and its xor over bytes. */"
      , "static void pudu_chacha20_block(const unsigned char *key, uint32_t counter, const unsigned char *nonce, unsigned char *out) {"
      , "  static const unsigned char quarters[8][4] = { {0, 4, 8, 12}, {1, 5, 9, 13}, {2, 6, 10, 14}, {3, 7, 11, 15}, {0, 5, 10, 15}, {1, 6, 11, 12}, {2, 7, 8, 13}, {3, 4, 9, 14} };"
      , "  uint32_t start[16] = {UINT32_C(0x61707865), UINT32_C(0x3320646e), UINT32_C(0x79622d32), UINT32_C(0x6b206574)}, v[16];"
      , "  for (int i = 0; i < 8; ++i)"
      , "    start[4 + i] = (uint32_t)key[4 * i] | (uint32_t)key[4 * i + 1] << 8 | (uint32_t)key[4 * i + 2] << 16 | (uint32_t)key[4 * i + 3] << 24;"
      , "  start[12] = counter;"
      , "  for (int i = 0; i < 3; ++i)"
      , "    start[13 + i] = (uint32_t)nonce[4 * i] | (uint32_t)nonce[4 * i + 1] << 8 | (uint32_t)nonce[4 * i + 2] << 16 | (uint32_t)nonce[4 * i + 3] << 24;"
      , "  memcpy(v, start, sizeof v);"
      , "  for (int round = 0; round < 10; ++round)"
      , "    for (int quarter = 0; quarter < 8; ++quarter) {"
      , "      const unsigned char *at = quarters[quarter];"
      , "      v[at[0]] += v[at[1]]; v[at[3]] ^= v[at[0]]; v[at[3]] = (v[at[3]] << 16) | (v[at[3]] >> 16);"
      , "      v[at[2]] += v[at[3]]; v[at[1]] ^= v[at[2]]; v[at[1]] = (v[at[1]] << 12) | (v[at[1]] >> 20);"
      , "      v[at[0]] += v[at[1]]; v[at[3]] ^= v[at[0]]; v[at[3]] = (v[at[3]] << 8) | (v[at[3]] >> 24);"
      , "      v[at[2]] += v[at[3]]; v[at[1]] ^= v[at[2]]; v[at[1]] = (v[at[1]] << 7) | (v[at[1]] >> 25);"
      , "    }"
      , "  for (int i = 0; i < 16; ++i) {"
      , "    uint32_t word = v[i] + start[i];"
      , "    out[4 * i] = (unsigned char)word;"
      , "    out[4 * i + 1] = (unsigned char)(word >> 8);"
      , "    out[4 * i + 2] = (unsigned char)(word >> 16);"
      , "    out[4 * i + 3] = (unsigned char)(word >> 24);"
      , "  }"
      , "}"
      , "static void pudu_chacha20_xor(const unsigned char *key, const unsigned char *nonce, const unsigned char *in, unsigned char *out, size_t length) {"
      , "  unsigned char stream[64];"
      , "  uint32_t counter = 1;"
      , "  for (size_t at = 0; at < length; at += 64) {"
      , "    size_t take = length - at < 64 ? length - at : 64;"
      , "    pudu_chacha20_block(key, counter++, nonce, stream);"
      , "    for (size_t i = 0; i < take; ++i) out[at + i] = in[at + i] ^ stream[i];"
      , "  }"
      , "}"
      ])
  , ("poly1305", [],
      [ "/* Poly1305 in five 26-bit limbs. Every input here is fed in whole 16-byte"
      , "   blocks: the sealing construction pads each part with zeros. */"
      , "typedef struct { uint32_t r[5], h[5], pad[4]; } pudu_poly1305;"
      , "static uint32_t pudu_poly1305_word(const unsigned char *at) {"
      , "  return (uint32_t)at[0] | (uint32_t)at[1] << 8 | (uint32_t)at[2] << 16 | (uint32_t)at[3] << 24;"
      , "}"
      , "static void pudu_poly1305_start(pudu_poly1305 *mac, const unsigned char *key) {"
      , "  mac->r[0] = pudu_poly1305_word(key) & UINT32_C(0x3ffffff);"
      , "  mac->r[1] = (pudu_poly1305_word(key + 3) >> 2) & UINT32_C(0x3ffff03);"
      , "  mac->r[2] = (pudu_poly1305_word(key + 6) >> 4) & UINT32_C(0x3ffc0ff);"
      , "  mac->r[3] = (pudu_poly1305_word(key + 9) >> 6) & UINT32_C(0x3f03fff);"
      , "  mac->r[4] = (pudu_poly1305_word(key + 12) >> 8) & UINT32_C(0x00fffff);"
      , "  for (int i = 0; i < 5; ++i) mac->h[i] = 0;"
      , "  for (int i = 0; i < 4; ++i) mac->pad[i] = pudu_poly1305_word(key + 16 + 4 * i);"
      , "}"
      , "static void pudu_poly1305_block(pudu_poly1305 *mac, const unsigned char *block) {"
      , "  const uint32_t *r = mac->r;"
      , "  uint32_t *h = mac->h;"
      , "  uint64_t d[5], carry = 0;"
      , "  h[0] += pudu_poly1305_word(block) & UINT32_C(0x3ffffff);"
      , "  h[1] += (pudu_poly1305_word(block + 3) >> 2) & UINT32_C(0x3ffffff);"
      , "  h[2] += (pudu_poly1305_word(block + 6) >> 4) & UINT32_C(0x3ffffff);"
      , "  h[3] += (pudu_poly1305_word(block + 9) >> 6) & UINT32_C(0x3ffffff);"
      , "  h[4] += (pudu_poly1305_word(block + 12) >> 8) | (UINT32_C(1) << 24);"
      , "  for (int i = 0; i < 5; ++i) {"
      , "    d[i] = 0;"
      , "    for (int j = 0; j < 5; ++j)"
      , "      d[i] += (uint64_t)h[j] * (j <= i ? r[i - j] : r[i - j + 5] * 5);"
      , "  }"
      , "  for (int i = 0; i < 5; ++i) {"
      , "    d[i] += carry;"
      , "    carry = d[i] >> 26;"
      , "    h[i] = (uint32_t)d[i] & UINT32_C(0x3ffffff);"
      , "  }"
      , "  h[0] += (uint32_t)carry * 5;"
      , "  h[1] += h[0] >> 26;"
      , "  h[0] &= UINT32_C(0x3ffffff);"
      , "}"
      , "/* Whole blocks, then the rest padded with zeros to one more. */"
      , "static void pudu_poly1305_padded(pudu_poly1305 *mac, const unsigned char *bytes, size_t length) {"
      , "  unsigned char last[16] = {0};"
      , "  for (; length >= 16; bytes += 16, length -= 16) pudu_poly1305_block(mac, bytes);"
      , "  if (length == 0) return;"
      , "  memcpy(last, bytes, length);"
      , "  pudu_poly1305_block(mac, last);"
      , "}"
      , "static void pudu_poly1305_finish(pudu_poly1305 *mac, unsigned char *tag) {"
      , "  uint32_t *h = mac->h, g[5], carry = 0, mask, words[4];"
      , "  uint64_t sum = 0;"
      , "  for (int i = 1; i < 5; ++i) { h[i] += carry; carry = h[i] >> 26; h[i] &= UINT32_C(0x3ffffff); }"
      , "  h[0] += carry * 5;"
      , "  h[1] += h[0] >> 26;"
      , "  h[0] &= UINT32_C(0x3ffffff);"
      , "  carry = 5;"
      , "  for (int i = 0; i < 5; ++i) { g[i] = h[i] + carry; carry = g[i] >> 26; g[i] &= UINT32_C(0x3ffffff); }"
      , "  /* carry is set exactly when h is at least the modulus. */"
      , "  mask = UINT32_C(0) - carry;"
      , "  for (int i = 0; i < 5; ++i) h[i] = (h[i] & ~mask) | (g[i] & mask);"
      , "  words[0] = h[0] | (h[1] << 26);"
      , "  words[1] = (h[1] >> 6) | (h[2] << 20);"
      , "  words[2] = (h[2] >> 12) | (h[3] << 14);"
      , "  words[3] = (h[3] >> 18) | (h[4] << 8);"
      , "  for (int i = 0; i < 4; ++i) {"
      , "    sum += (uint64_t)words[i] + mac->pad[i];"
      , "    tag[4 * i] = (unsigned char)sum;"
      , "    tag[4 * i + 1] = (unsigned char)(sum >> 8);"
      , "    tag[4 * i + 2] = (unsigned char)(sum >> 16);"
      , "    tag[4 * i + 3] = (unsigned char)(sum >> 24);"
      , "    sum >>= 32;"
      , "  }"
      , "}"
      ])
  , ("seal_tag", ["chacha20", "poly1305", "kernel_put"],
      [ "/* The tag over the associated data and the ciphertext, each padded, then their lengths. */"
      , "static void pudu_seal_tag(const unsigned char *key, const unsigned char *nonce, pudu_text associated, const unsigned char *sealed, size_t length, unsigned char *tag) {"
      , "  unsigned char block[64], lengths[16];"
      , "  pudu_poly1305 mac;"
      , "  pudu_chacha20_block(key, 0, nonce, block);"
      , "  pudu_poly1305_start(&mac, block);"
      , "  pudu_poly1305_padded(&mac, associated.bytes, associated.length);"
      , "  pudu_poly1305_padded(&mac, sealed, length);"
      , "  pudu_kernel_put(lengths, (uint64_t)associated.length, 8);"
      , "  pudu_kernel_put(lengths + 8, (uint64_t)length, 8);"
      , "  pudu_poly1305_block(&mac, lengths);"
      , "  pudu_poly1305_finish(&mac, tag);"
      , "}"
      ])
  , ("seal_fits", [],
      [ "static int pudu_seal_fits(pudu_box *key, pudu_box *nonce) {"
      , "  return key->fields[0].text.length == 32 && nonce->fields[0].text.length == 12;"
      , "}"
      ])
  , ("seal", ["seal_tag", "bytes_wrap", "text_allocate", "memory_failure"],
      [ "/* The ciphertext with its 16-byte tag appended. */"
      , "static pudu_box *pudu_seal(pudu_box *key, pudu_box *nonce, pudu_box *message, pudu_box *associated) {"
      , "  pudu_text plain = message->fields[0].text;"
      , "  unsigned char *out;"
      , "  pudu_text sealed;"
      , "  if (plain.length > SIZE_MAX - 16) pudu_memory_failure();"
      , "  sealed = pudu_text_allocate(plain.length + 16, &out);"
      , "  pudu_chacha20_xor(key->fields[0].text.bytes, nonce->fields[0].text.bytes, plain.bytes, out, plain.length);"
      , "  pudu_seal_tag(key->fields[0].text.bytes, nonce->fields[0].text.bytes, associated->fields[0].text, out, plain.length, out + plain.length);"
      , "  return pudu_bytes_wrap(sealed);"
      , "}"
      ])
  , ("open_fits", ["seal_tag"],
      [ "/* Whether the lengths are right and the carried tag is the computed one. */"
      , "static int pudu_open_fits(pudu_box *key, pudu_box *nonce, pudu_box *sealed, pudu_box *associated) {"
      , "  pudu_text bytes = sealed->fields[0].text;"
      , "  unsigned char tag[16];"
      , "  unsigned difference = 0;"
      , "  if (key->fields[0].text.length != 32 || nonce->fields[0].text.length != 12 || bytes.length < 16) return 0;"
      , "  pudu_seal_tag(key->fields[0].text.bytes, nonce->fields[0].text.bytes, associated->fields[0].text, bytes.bytes, bytes.length - 16, tag);"
      , "  for (int i = 0; i < 16; ++i) difference |= (unsigned)(tag[i] ^ bytes.bytes[bytes.length - 16 + i]);"
      , "  return difference == 0;"
      , "}"
      ])
  , ("open_sealed", ["chacha20", "bytes_wrap", "text_allocate"],
      [ "/* The message under a tag open_fits accepted. */"
      , "static pudu_box *pudu_open_sealed(pudu_box *key, pudu_box *nonce, pudu_box *sealed) {"
      , "  pudu_text bytes = sealed->fields[0].text;"
      , "  unsigned char *out;"
      , "  pudu_text plain = pudu_text_allocate(bytes.length - 16, &out);"
      , "  pudu_chacha20_xor(key->fields[0].text.bytes, nonce->fields[0].text.bytes, bytes.bytes, out, bytes.length - 16);"
      , "  return pudu_bytes_wrap(plain);"
      , "}"
      ])
  ]
